// src/pages/FuelSlipDetails.jsx
import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
  Box,
  Paper,
  Typography,
  Grid,
  Card,
  CardContent,
  Button,
  Chip,
  Stack,
  Divider,
  CircularProgress,
  Alert,
  IconButton,
  Tooltip,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  DialogContentText,
} from '@mui/material';
import {
  ArrowBack as ArrowBackIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  LocalGasStation,
  Person,
  DirectionsCar,
  Event,
  AttachMoney,
  LocationOn,
  Receipt,
  CheckCircle,
  Cancel,
  Print as PrintIcon,
  Link as LinkIcon,
} from '@mui/icons-material';
import { fuelService } from '../services/fuelService';
import { tripService } from '../services/tripService';

// Currency formatter for South African Rand (ZAR)
const formatCurrency = (amount) => {
  if (amount === null || amount === undefined) return 'R 0.00';
  const numAmount = typeof amount === 'string' ? parseFloat(amount) : amount;
  return new Intl.NumberFormat('en-ZA', {
    style: 'currency',
    currency: 'ZAR',
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(numAmount);
};

// Format number with commas
const formatNumber = (num) => {
  if (num === null || num === undefined) return '0.00';
  const number = typeof num === 'string' ? parseFloat(num) : num;
  return new Intl.NumberFormat('en-ZA', {
    minimumFractionDigits: 1,
    maximumFractionDigits: 1,
  }).format(number);
};

// Compact Info Item Component
const InfoItem = ({ label, value, icon: Icon, color = 'primary' }) => (
  <Paper
    sx={{
      p: 1.5,
      bgcolor: 'grey.50',
      borderRadius: 1,
      border: '1px solid',
      borderColor: 'divider',
      height: '100%',
    }}
  >
    <Stack direction="row" alignItems="center" spacing={1}>
      {Icon && (
        <Box
          sx={{
            bgcolor: `${color}.light`,
            borderRadius: 1,
            p: 0.5,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
          }}
        >
          <Icon sx={{ fontSize: '1rem', color: `${color}.main` }} />
        </Box>
      )}
      <Box>
        <Typography variant="caption" color="text.secondary" sx={{ fontSize: '0.65rem' }}>
          {label}
        </Typography>
        <Typography variant="body2" fontWeight="500" sx={{ fontSize: '0.8rem' }}>
          {value || 'N/A'}
        </Typography>
      </Box>
    </Stack>
  </Paper>
);

const FuelSlipDetails = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [slip, setSlip] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [tripDetails, setTripDetails] = useState(null);

  useEffect(() => {
    if (id) {
      fetchSlipDetails();
    } else {
      setError('No fuel slip ID provided');
      setLoading(false);
    }
  }, [id]);

  const fetchSlipDetails = async () => {
    setLoading(true);
    setError(null);
    try {
      console.log(`📤 Fetching fuel slip with ID: ${id}`);
      const data = await fuelService.getFuelSlipById(id);
      console.log('✅ Fuel slip fetched:', data);
      setSlip(data);

      // If trip is linked, fetch trip details
      if (data.tripId) {
        try {
          const trip = await tripService.getTripById(data.tripId);
          setTripDetails(trip);
        } catch (tripErr) {
          console.warn('Could not fetch trip details:', tripErr);
        }
      }
    } catch (err) {
      console.error('❌ Failed to fetch fuel slip details:', err);
      setError(err.message || 'Failed to load fuel slip details');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async () => {
    setDeleting(true);
    try {
      await fuelService.deleteFuelSlip(id);
      setDeleteDialogOpen(false);
      navigate('/fuel/slips');
    } catch (err) {
      console.error('Failed to delete fuel slip:', err);
      setError(err.message || 'Failed to delete fuel slip');
      setDeleting(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const handleGoBack = () => {
    navigate('/fuel/slips');
  };

  const handleEdit = () => {
    navigate(`/fuel/slips/${id}/edit`);
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="60vh">
        <Box textAlign="center">
          <CircularProgress size={40} />
          <Typography variant="body1" mt={1} sx={{ fontSize: '0.9rem' }}>
            Loading fuel slip details...
          </Typography>
        </Box>
      </Box>
    );
  }

  if (error) {
    return (
      <Box sx={{ p: 2 }}>
        <Alert 
          severity="error" 
          sx={{ fontSize: '0.8rem', mb: 2 }}
          action={
            <Button color="inherit" size="small" onClick={handleGoBack}>
              Go Back
            </Button>
          }
        >
          {error}
        </Alert>
      </Box>
    );
  }

  if (!slip) {
    return (
      <Box sx={{ p: 2 }}>
        <Alert 
          severity="warning" 
          sx={{ fontSize: '0.8rem', mb: 2 }}
          action={
            <Button color="inherit" size="small" onClick={handleGoBack}>
              Go Back
            </Button>
          }
        >
          Fuel slip not found
        </Alert>
      </Box>
    );
  }

  return (
    <Box sx={{ p: { xs: 1, sm: 1.5, md: 2 } }}>
      {/* Delete Confirmation Dialog */}
      <Dialog
        open={deleteDialogOpen}
        onClose={() => setDeleteDialogOpen(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle sx={{ fontSize: '1rem' }}>
          <DeleteIcon sx={{ verticalAlign: 'middle', mr: 1, color: 'error.main' }} />
          Delete Fuel Slip
        </DialogTitle>
        <DialogContent>
          <DialogContentText sx={{ fontSize: '0.9rem' }}>
            Are you sure you want to delete fuel slip #{slip.slipNumber || slip.id}? 
            This action cannot be undone.
          </DialogContentText>
        </DialogContent>
        <DialogActions sx={{ p: 2 }}>
          <Button onClick={() => setDeleteDialogOpen(false)} size="small" sx={{ fontSize: '0.8rem' }}>
            Cancel
          </Button>
          <Button
            onClick={handleDelete}
            variant="contained"
            color="error"
            disabled={deleting}
            size="small"
            sx={{ fontSize: '0.8rem' }}
          >
            {deleting ? <CircularProgress size={18} /> : 'Delete'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Header - Compact */}
      <Box display="flex" justifyContent="space-between" alignItems="center" mb={2} flexWrap="wrap" gap={1}>
        <Stack direction="row" alignItems="center" spacing={1}>
          <IconButton onClick={handleGoBack} size="small">
            <ArrowBackIcon sx={{ fontSize: '0.9rem' }} />
          </IconButton>
          <Box>
            <Typography variant="h6" fontWeight="600" sx={{ fontSize: '1rem' }}>
              Fuel Slip Details
            </Typography>
            <Typography variant="caption" color="text.secondary" sx={{ fontSize: '0.7rem' }}>
              #{slip.slipNumber || slip.id} • {slip.transactionDate ? new Date(slip.transactionDate).toLocaleDateString() : 'N/A'}
            </Typography>
          </Box>
        </Stack>
        <Stack direction="row" spacing={0.75}>
          <Tooltip title="Print">
            <IconButton size="small" onClick={handlePrint} sx={{ p: 0.5 }}>
              <PrintIcon sx={{ fontSize: '0.9rem' }} />
            </IconButton>
          </Tooltip>
          <Tooltip title="Edit">
            <IconButton
              size="small"
              color="primary"
              onClick={handleEdit}
              sx={{ p: 0.5 }}
            >
              <EditIcon sx={{ fontSize: '0.9rem' }} />
            </IconButton>
          </Tooltip>
          <Tooltip title="Delete">
            <IconButton
              size="small"
              color="error"
              onClick={() => setDeleteDialogOpen(true)}
              sx={{ p: 0.5 }}
            >
              <DeleteIcon sx={{ fontSize: '0.9rem' }} />
            </IconButton>
          </Tooltip>
        </Stack>
      </Box>

      {/* Summary Card - Compact */}
      <Card sx={{ mb: 2 }}>
        <CardContent sx={{ p: { xs: 1.5, sm: 2 } }}>
          <Grid container spacing={2}>
            <Grid item xs={12} md={8}>
              <Stack spacing={1}>
                <Stack direction="row" alignItems="center" spacing={1}>
                  <LocalGasStation sx={{ fontSize: '1.2rem', color: 'primary.main' }} />
                  <Typography variant="h5" fontWeight="bold" sx={{ fontSize: '1.1rem' }}>
                    {formatCurrency(slip.totalAmount)}
                  </Typography>
                  <Chip
                    label={slip.finalized ? 'Finalized' : 'Pending'}
                    size="small"
                    color={slip.finalized ? 'success' : 'warning'}
                    icon={slip.finalized ? <CheckCircle sx={{ fontSize: '0.7rem' }} /> : <Cancel sx={{ fontSize: '0.7rem' }} />}
                    sx={{ height: 20, fontSize: '0.6rem' }}
                  />
                </Stack>
                <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
                  <Typography variant="caption" color="text.secondary" sx={{ fontSize: '0.65rem' }}>
                    <strong>Quantity:</strong> {formatNumber(slip.quantity)} L
                  </Typography>
                  <Typography variant="caption" color="text.secondary" sx={{ fontSize: '0.65rem' }}>
                    <strong>Unit Price:</strong> {formatCurrency(slip.unitPrice)}/L
                  </Typography>
                  {slip.quantity && slip.totalAmount && (
                    <Typography variant="caption" color="text.secondary" sx={{ fontSize: '0.65rem' }}>
                      <strong>Effective Price:</strong> {formatCurrency(parseFloat(slip.totalAmount) / parseFloat(slip.quantity))}/L
                    </Typography>
                  )}
                </Stack>
              </Stack>
            </Grid>
            <Grid item xs={12} md={4}>
              <Stack alignItems={{ xs: 'flex-start', md: 'flex-end' }} spacing={0.5}>
                <Typography variant="caption" color="text.secondary" sx={{ fontSize: '0.6rem' }}>
                  Slip #: {slip.slipNumber || 'N/A'}
                </Typography>
                {slip.tripId && (
                  <Chip
                    size="small"
                    icon={<LinkIcon sx={{ fontSize: '0.7rem' }} />}
                    label={`Trip: ${tripDetails?.tripNumber || slip.tripId}`}
                    color="info"
                    variant="outlined"
                    sx={{ height: 20, fontSize: '0.55rem' }}
                  />
                )}
              </Stack>
            </Grid>
          </Grid>
        </CardContent>
      </Card>

      {/* Trip Details if linked */}
      {tripDetails && (
        <Box sx={{ mb: 2, p: 1.5, bgcolor: 'info.light', borderRadius: 1 }}>
          <Typography variant="caption" sx={{ fontSize: '0.7rem' }}>
            <strong>Linked Trip:</strong> {tripDetails.tripNumber} | 
            <strong> Status:</strong> {tripDetails.status} |
            <strong> Origin:</strong> {tripDetails.originLocation || tripDetails.originCity || 'N/A'} →
            <strong> Destination:</strong> {tripDetails.destinationLocation || tripDetails.destinationCity || 'N/A'}
          </Typography>
        </Box>
      )}

      {/* Details Grid - Compact */}
      <Grid container spacing={1.5}>
        <Grid item xs={12} md={6}>
          <Stack spacing={1.5}>
            <InfoItem
              label="Driver"
              value={`${slip.driverName || 'N/A'} (ID: ${slip.driverId || 'N/A'})`}
              icon={Person}
              color="secondary"
            />
            <InfoItem
              label="Vehicle"
              value={`${slip.vehicleRegNumber || 'N/A'} (ID: ${slip.vehicleId || 'N/A'})`}
              icon={DirectionsCar}
              color="info"
            />
            <InfoItem
              label="Transaction Date"
              value={slip.transactionDate ? new Date(slip.transactionDate).toLocaleString() : 'N/A'}
              icon={Event}
              color="warning"
            />
          </Stack>
        </Grid>

        <Grid item xs={12} md={6}>
          <Stack spacing={1.5}>
            <InfoItem
              label="Fuel Station"
              value={slip.stationName || slip.location || 'N/A'}
              icon={LocationOn}
              color="primary"
            />
            <InfoItem
              label="Receipt Number"
              value={slip.receiptNumber || 'N/A'}
              icon={Receipt}
              color="success"
            />
            <InfoItem
              label="Status"
              value={slip.finalized ? 'Finalized' : 'Pending'}
              icon={slip.finalized ? CheckCircle : Cancel}
              color={slip.finalized ? 'success' : 'warning'}
            />
          </Stack>
        </Grid>

        {/* Fuel Details */}
        <Grid item xs={12}>
          <Divider sx={{ my: 1.5 }} />
          <Typography variant="subtitle2" sx={{ fontSize: '0.8rem', fontWeight: 600, mb: 1 }}>
            Fuel Details
          </Typography>
          <Paper variant="outlined" sx={{ p: 1.5, bgcolor: 'grey.50' }}>
            <Grid container spacing={1.5}>
              <Grid item xs={6} md={3}>
                <Typography variant="caption" color="text.secondary" sx={{ fontSize: '0.6rem' }}>
                  Fuel Type
                </Typography>
                <Typography variant="body2" sx={{ fontSize: '0.75rem' }}>
                  {slip.fuelType || 'N/A'}
                </Typography>
              </Grid>
              <Grid item xs={6} md={3}>
                <Typography variant="caption" color="text.secondary" sx={{ fontSize: '0.6rem' }}>
                  Payment Method
                </Typography>
                <Typography variant="body2" sx={{ fontSize: '0.75rem' }}>
                  {slip.paymentMethod || 'N/A'}
                </Typography>
              </Grid>
              <Grid item xs={6} md={3}>
                <Typography variant="caption" color="text.secondary" sx={{ fontSize: '0.6rem' }}>
                  Odometer Reading
                </Typography>
                <Typography variant="body2" sx={{ fontSize: '0.75rem' }}>
                  {slip.odometerReading ? formatNumber(slip.odometerReading) : 'N/A'}
                </Typography>
              </Grid>
              <Grid item xs={6} md={3}>
                <Typography variant="caption" color="text.secondary" sx={{ fontSize: '0.6rem' }}>
                  Pump Number
                </Typography>
                <Typography variant="body2" sx={{ fontSize: '0.75rem' }}>
                  {slip.pumpNumber || 'N/A'}
                </Typography>
              </Grid>
            </Grid>
          </Paper>
        </Grid>

        {/* Notes Section */}
        {slip.notes && (
          <Grid item xs={12}>
            <Divider sx={{ my: 1.5 }} />
            <Typography variant="subtitle2" sx={{ fontSize: '0.8rem', fontWeight: 600, mb: 1 }}>
              Notes
            </Typography>
            <Paper variant="outlined" sx={{ p: 1.5, bgcolor: 'grey.50' }}>
              <Typography variant="body2" sx={{ fontSize: '0.8rem' }}>
                {slip.notes}
              </Typography>
            </Paper>
          </Grid>
        )}

        {/* Audit Trail */}
        <Grid item xs={12}>
          <Divider sx={{ my: 1.5 }} />
          <Typography variant="subtitle2" sx={{ fontSize: '0.8rem', fontWeight: 600, mb: 1 }}>
            Audit Trail
          </Typography>
          <Paper variant="outlined" sx={{ p: 1.5, bgcolor: 'grey.50' }}>
            <Stack spacing={0.5}>
              <Box display="flex" justifyContent="space-between" alignItems="center">
                <Typography variant="caption" sx={{ fontSize: '0.65rem' }}>
                  <strong>Created:</strong> {slip.createdAt ? new Date(slip.createdAt).toLocaleString() : 'N/A'}
                </Typography>
                <Typography variant="caption" color="text.secondary" sx={{ fontSize: '0.6rem' }}>
                  By: {slip.createdBy || 'System'}
                </Typography>
              </Box>
              {slip.updatedAt && slip.updatedAt !== slip.createdAt && (
                <Box display="flex" justifyContent="space-between" alignItems="center">
                  <Typography variant="caption" sx={{ fontSize: '0.65rem' }}>
                    <strong>Last Updated:</strong> {new Date(slip.updatedAt).toLocaleString()}
                  </Typography>
                  <Typography variant="caption" color="text.secondary" sx={{ fontSize: '0.6rem' }}>
                    By: {slip.updatedBy || 'System'}
                  </Typography>
                </Box>
              )}
              {slip.verificationDate && (
                <Box display="flex" justifyContent="space-between" alignItems="center">
                  <Typography variant="caption" sx={{ fontSize: '0.65rem' }}>
                    <strong>Verified:</strong> {new Date(slip.verificationDate).toLocaleString()}
                  </Typography>
                  <Typography variant="caption" color="text.secondary" sx={{ fontSize: '0.6rem' }}>
                    By: {slip.verifiedBy || 'System'}
                  </Typography>
                </Box>
              )}
            </Stack>
          </Paper>
        </Grid>
      </Grid>

      {/* Actions Footer */}
      <Box sx={{ mt: 3, display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 1 }}>
        <Button
          variant="outlined"
          startIcon={<ArrowBackIcon sx={{ fontSize: '0.9rem' }} />}
          onClick={handleGoBack}
          size="small"
          sx={{ fontSize: '0.8rem' }}
        >
          Back to Fuel Slips
        </Button>
        <Stack direction="row" spacing={0.75}>
          <Button
            variant="contained"
            startIcon={<EditIcon sx={{ fontSize: '0.9rem' }} />}
            onClick={handleEdit}
            size="small"
            sx={{ fontSize: '0.8rem' }}
          >
            Edit Slip
          </Button>
          <Button
            variant="outlined"
            color="error"
            startIcon={<DeleteIcon sx={{ fontSize: '0.9rem' }} />}
            onClick={() => setDeleteDialogOpen(true)}
            size="small"
            sx={{ fontSize: '0.8rem' }}
          >
            Delete
          </Button>
        </Stack>
      </Box>
    </Box>
  );
};

export default FuelSlipDetails;
